267	        ownerPageDto.setSize(ownerPage.getSize());
268	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
269	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
270	        return ownerPageDto;
271	    }
